        /* [pystencils-sfg] Formatting may add illegal spaces between angular brackets in `<<< >>>` */
        walberla::pystencils::DiffusiveFluxKernelThermalizedSinglePrecisionCUDA_kernels::DiffusiveFluxKernelThermalizedSinglePrecisionCUDA<<< __grid_size, __block_size, 0, exTag.stream() >>>(_data_density, _data_flux, _size_density_0, _size_density_1, _size_density_2, _stride_density_0, _stride_density_1, _stride_density_2, _stride_flux_0, _stride_flux_1, _stride_flux_2, _stride_flux_3, block_offset_0, block_offset_1, block_offset_2, diffusion, grid_size_0, grid_size_1, grid_size_2, seed, time_step);
      /* clang-format on */
    }
  } else {
    {
      const dim3 __block_size{8, 8, 4};
      const std::tuple<uint32_t, uint32_t, uint32_t> __work_items{_size_density_0, _size_density_1, _size_density_2};
      const dim3 __grid_size{(std::get<0>(__work_items) + __block_size.x - 1) / __block_size.x, (std::get<1>(__work_items) + __block_size.y - 1) / __block_size.y, (std::get<2>(__work_items) + __block_size.z - 1) / __block_size.z};
      /* clang-format off */
        /* [pystencils-sfg] Formatting may add illegal spaces between angular brackets in `<<< >>>` */
        walberla::pystencils::DiffusiveFluxKernelThermalizedSinglePrecisionCUDA_kernels::DiffusiveFluxKernelThermalizedSinglePrecisionCUDA<<< __grid_size, __block_size, 0, exTag.stream() >>>(_data_density, _data_flux, _size_density_0, _size_density_1, _size_density_2, _stride_density_0, _stride_density_1, _stride_density_2, _stride_flux_0, _stride_flux_1, _stride_flux_2, _stride_flux_3, block_offset_0, block_offset_1, block_offset_2, diffusion, grid_size_0, grid_size_1, grid_size_2, seed, time_step);
